import json,sys
from pathlib import Path
cid,path,oracle_path=sys.argv[1:]
doc=json.loads(Path(path).read_text())
nr=doc.get('normalized_result') or {}
gaps=nr.get('extraction_gaps') or []
def rel(p):
    if not isinstance(p,str): return None
    marker='_extract/'
    if marker in p: return p.split(marker,1)[1]
    return p.removeprefix('$output/')
all_gaps=[g.get('relative_path') for g in gaps if isinstance(g,dict)]
gap_rels=[rel(p) for p in all_gaps]
rem=[]
for d in nr.get('diagnostics') or []:
    if not isinstance(d,dict): continue
    report=d.get('report') or {}
    if report.get('__typename__')=='MaliciousSymlinkRemoved': rem.append(rel(report.get('link')))
rows=[]
for line in Path(oracle_path).read_text().splitlines():
    cols=line.split('\t')
    if len(cols)>=2 and cols[1]=='char-device':
        p=cols[0].removeprefix('./').lstrip('/')
        rows.append({'path':p,'detail':cols[2] if len(cols)>2 else None,'gaps':[x for x in gap_rels if x==p], 'removals':[x for x in rem if x==p]})
out={'id':cid,'gap_count':len(gaps),'gap_paths':all_gaps,'gap_dev_paths':[p for p in all_gaps if isinstance(p,str) and '/dev/' in p or isinstance(p,str) and p.startswith('dev/')], 'removed_dev_paths':[p for p in rem if isinstance(p,str) and (p.startswith('dev/') or '/dev/' in p)], 'malicious_symlink_removed_count':len(rem),'char_dispositions':rows}
print(json.dumps(out,sort_keys=True,ensure_ascii=False,indent=2))

